/**
 * Generated by scaffold-fixtures-per-entity. Inserts a Payments row
 * directly via the repository. Useful for tests that need a pre-seeded record
 * without going through the full HTTP create flow.
 */
import { DataSource } from 'typeorm';

export interface CreatePaymentsInput {
  [key: string]: unknown;
}

export async function createTestPayments(
  dataSource: DataSource,
  overrides: CreatePaymentsInput = {},
): Promise<Record<string, unknown>> {
  const meta = dataSource.entityMetadatas.find(
    (m) => m.name === 'Payments' || m.tableName === 'payments',
  );
  if (!meta) {
    throw new Error('createTestPayments: Payments entity not registered with the DataSource');
  }
  const repo = dataSource.getRepository(meta.target);
  const row: Record<string, unknown> = {
    paymentNo: 'test-paymentNo',
    amountPoisha: 0,
    currency: 'test-currency',
    status: 'test-status',
    webhookConfirmed: false,
    ...overrides,
  };
  const saved = await repo.save(row as never);
  return saved as unknown as Record<string, unknown>;
}
